raw_code:
#############################
# Knowledgebase Role
#############################
resource "aws_iam_role" "kb_role" {
  name = "kb_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "bedrock.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.aws-account-id.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:bedrock:${var.region}:${data.aws_caller_identity.aws-account-id.account_id}:knowledge-base/*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "kb_role_policy" {
  name = "kb_role_policy_${var.cgid}"
  role = aws_iam_role.kb_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "bedrock:InvokeModel"
        Effect   = "Allow"
        Resource = local.bedrock_model_arn
      },
      {
        Sid      = "S3ListBucketStatement"
        Action   = [
          "s3:ListBucket",
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.kb_s3_bucket.arn,
          "${aws_s3_bucket.kb_s3_bucket.arn}/*"
        ]
      },
      {
        Action   = "aoss:APIAccessAll"
        Effect   = "Allow"
        Resource = aws_opensearchserverless_collection.kb_oss_collection.arn
      }
    ]
  })
}

resource "time_sleep" "kb_role_policy_sleep" {
  create_duration = "20s"
  depends_on      = [aws_iam_role_policy.kb_role_policy]
}

#############################
# Knowledgebase
#############################
resource "aws_bedrockagent_knowledge_base" "kb" {
  name     = "kb-${var.cgid}"
  role_arn = aws_iam_role.kb_role.arn
  knowledge_base_configuration {
    vector_knowledge_base_configuration {
      embedding_model_arn = local.bedrock_model_arn
    }
    type = "VECTOR"
  }
  storage_configuration {
    type = "OPENSEARCH_SERVERLESS"
    opensearch_serverless_configuration {
      collection_arn    = aws_opensearchserverless_collection.kb_oss_collection.arn
      vector_index_name = opensearch_index.kb_oss_index.name
      field_mapping {
        vector_field   = "kb-vector"
        text_field     = "AMAZON_BEDROCK_TEXT_CHUNK"
        metadata_field = "AMAZON_BEDROCK_METADATA"
      }
    }
  }
  depends_on = [
    opensearch_index.kb_oss_index,
    time_sleep.kb_role_policy_sleep
  ]
}

resource "aws_bedrockagent_data_source" "kb_data_source" {
  knowledge_base_id = aws_bedrockagent_knowledge_base.kb.id
  name              = "kb-datasource-${var.cgid}"
  data_source_configuration {
    type = "S3"
    s3_configuration {
      bucket_arn = aws_s3_bucket.kb_s3_bucket.arn
    }
  }
  vector_ingestion_configuration {
    chunking_configuration {
      chunking_strategy = "FIXED_SIZE"
      fixed_size_chunking_configuration {
        max_tokens         = 512
        overlap_percentage = 20
      }
    }
  }
}

resource "terraform_data" "kb_ingestion" {
  depends_on = [ aws_bedrockagent_data_source.kb_data_source ]

  triggers_replace = {
    kb_id    = aws_bedrockagent_knowledge_base.kb.id
    kb_ds_id = aws_bedrockagent_data_source.kb_data_source.data_source_id
  }

  provisioner "local-exec" {
    when       = create
    on_failure = fail
    command    = "aws bedrock-agent start-ingestion-job --knowledge-base-id ${self.triggers_replace.kb_id} --data-source-id ${self.triggers_replace.kb_ds_id} --region ${var.region} --profile ${var.profile}"
  }
}

#############################
# Code Interpreter Role
#############################
resource "aws_iam_role" "code_interpreter_role" {
  name = "agentcore_code_interpreter_execution_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "bedrock-agentcore.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "code_interpreter_role_policy" {
  role   = aws_iam_role.code_interpreter_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.kb_code_interpreter_bucket.arn,
          "${aws_s3_bucket.kb_code_interpreter_bucket.arn}/*"
        ]
      }
    ]
  })
}

#############################
# Agent Runtime Role
#############################
resource "aws_iam_role" "agent_runtime_role" {
  name = "agentcore_agent_runtime_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "bedrock-agentcore.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "agent_runtime_role_policy" {
  role   = aws_iam_role.agent_runtime_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BedrockModelInvocation"
        Effect = "Allow"
        Action = [
          "bedrock:InvokeModel",
          "bedrock:InvokeModelWithResponseStream"
        ]
        "Resource": "*"
      },
      {
        Sid    = "CodeInterpreterAccess"
        Effect = "Allow"
        Action = [
          "bedrock-agentcore:InvokeCodeInterpreter",
          "bedrock-agentcore:StartCodeInterpreterSession",
          "bedrock-agentcore:StopCodeInterpreterSession"
        ]
        "Resource": "*"
      },
      {
        Sid    = "KnowledgeBaseAccess"
        Effect = "Allow"
        Action = [
          "bedrock:Retrieve",
          "bedrock:RetrieveAndGenerate"
        ]
        "Resource": aws_bedrockagent_knowledge_base.kb.arn
      }
    ]
  })
}

#############################
# Starting User
#############################
resource "aws_iam_user" "starting_user" {
  name = "sandy_${var.cgid}"
}

resource "aws_iam_access_key" "starting_user_key" {
  user = aws_iam_user.starting_user.name
}

# Iam enumeration is not part of the challenge. Might as well make it easy
resource "aws_iam_user_policy_attachment" "starting_user_iam_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_policy" "starting_user_bedrock_policy" {
  name = "agent_access_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "BedrockReadOnly"
        Effect = "Allow"
        Action = [
          "bedrock:Get*",
          "bedrock:List*",
          "bedrock-agentcore:Get*",
          "bedrock-agentcore:List*"
        ],
        Resource = "*"
      },
      {
        Sid    = "CodeInterpreterManagement"
        Effect = "Allow",
        Action = [
          "bedrock-agentcore:*CodeInterpreter*"
        ],
        Resource = "*"
      },
      {
        Sid    = "CodeInterpreterRoleManagement"
        Effect = "Allow",
        Action = [
          "iam:PassRole"
        ],
        Resource = "arn:aws:iam::${data.aws_caller_identity.aws-account-id.account_id}:role/agentcore_*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "starting_user_bedrock_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = aws_iam_policy.starting_user_bedrock_policy.arn
}

resource "aws_opensearchserverless_access_policy" "kb_oss_collection_policy" {
  name = "oss-access-${var.cgid}"
  type = "data"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "index"
          Resource = [
            "index/kb-oss-collection-${var.cgid}/*"
          ]
          Permission = [
            "aoss:CreateIndex",
            "aoss:DeleteIndex",
            "aoss:DescribeIndex",
            "aoss:ReadDocument",
            "aoss:UpdateIndex",
            "aoss:WriteDocument"
          ]
        },
        {
          ResourceType = "collection"
          Resource = [
            "collection/kb-oss-collection-${var.cgid}"
          ]
          Permission = [
            "aoss:CreateCollectionItems",
            "aoss:DescribeCollectionItems",
            "aoss:UpdateCollectionItems"
          ]
        }
      ],
      Principal = [
        aws_iam_role.kb_role.arn,
        data.aws_caller_identity.aws-account-id.arn
      ]
    }
  ])
}

# OpenSearch collection data encryption policy
resource "aws_opensearchserverless_security_policy" "kb_oss_encryption_policy" {
  name = "oss-encryption-${var.cgid}"
  type = "encryption"
  policy = jsonencode({
    Rules = [
      {
        Resource = [
          "collection/kb-oss-collection-${var.cgid}"
        ]
        ResourceType = "collection"
      }
    ],
    AWSOwnedKey = true
  })
}

# OpenSearch collection network policy
resource "aws_opensearchserverless_security_policy" "kb_oss_network_policy" {
  name = "oss-network-${var.cgid}"
  type = "network"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Resource = [
            "collection/kb-oss-collection-${var.cgid}"
          ]
        },
        {
          ResourceType = "dashboard"
          Resource = [
            "collection/kb-oss-collection-${var.cgid}"
          ]
        }
      ]
      AllowFromPublic = true
    }
  ])
}

# OpenSearch resource
resource "aws_opensearchserverless_collection" "kb_oss_collection" {
  name = "kb-oss-collection-${var.cgid}"
  type = "VECTORSEARCH"
  depends_on = [
    aws_opensearchserverless_access_policy.kb_oss_collection_policy,
    aws_opensearchserverless_security_policy.kb_oss_encryption_policy,
    aws_opensearchserverless_security_policy.kb_oss_network_policy
  ]
}

# Creating the index *immediately* after the collection sometimes fails on permissions errors.
# The access policy needs a few seconds to get recognized.
resource "time_sleep" "kb_oss_collection_sleep" {
  create_duration = "20s"
  depends_on      = [aws_opensearchserverless_collection.kb_oss_collection]
}

# OpenSearch index creation
resource "opensearch_index" "kb_oss_index" {
  name                           = "kb-index-${var.cgid}"
  number_of_shards               = "2"
  number_of_replicas             = "0"
  index_knn                      = true
  index_knn_algo_param_ef_search = "512"
  mappings                       = <<-EOF
    {
      "properties": {
        "kb-vector": {
          "type": "knn_vector",
          "dimension": 1024,
          "method": {
            "name": "hnsw",
            "engine": "faiss",
            "parameters": {
              "m": 16,
              "ef_construction": 512
            },
            "space_type": "l2"
          }
        },
        "AMAZON_BEDROCK_METADATA": {
          "type": "text",
          "index": "false"
        },
        "AMAZON_BEDROCK_TEXT_CHUNK": {
          "type": "text",
          "index": "true"
        }
      }
    }
  EOF
  force_destroy                  = true
  depends_on                     = [time_sleep.kb_oss_collection_sleep]
}

# Bucket the KnowledgeBase is trained on
resource "aws_s3_bucket" "kb_s3_bucket" {
  bucket = "cg-knowldegebase-bucket-${replace(var.cgid, "/[^a-z0-9-.]/", "-")}"
}

resource "aws_s3_object" "example_file" {
  bucket       = aws_s3_bucket.kb_s3_bucket.bucket
  key          = "flag.txt"
  content      = "FLAG{ar3_y0u_@n_ag3nt?}"
  content_type = "text/plain"
}

# Bucket the CodeInterpreter role has access to
resource "aws_s3_bucket" "kb_code_interpreter_bucket" {
  bucket = "cg-codeinterpreter-artifacts-${replace(var.cgid, "/[^a-z0-9-.]/", "-")}"
}

resource "aws_s3_object" "decoy_file" {
  bucket       = aws_s3_bucket.kb_code_interpreter_bucket.bucket
  key          = "flag.txt"
  content      = "Your flag is in another location..."
  content_type = "text/plain"
}

#############################
# Elastic Beanstalk Environment
#############################

resource "aws_elastic_beanstalk_environment" "eb_env" {
  name                = replace("${var.cgid}-env", "_", "-")
  application         = aws_elastic_beanstalk_application.eb_app.name
  # Dynamically use the latest Python solution stack found by the data source
  solution_stack_name = data.aws_elastic_beanstalk_solution_stack.python_stack.name

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "SECONDARY_ACCESS_KEY"
    value     = aws_iam_access_key.secondary_key.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "SECONDARY_SECRET_KEY"
    value     = aws_iam_access_key.secondary_key.secret
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }
  # Launch this in the CG VPC
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = aws_subnet.subnet.id
  }
}

resource "aws_iam_policy" "admin_user_policy" {
  name = "${var.cgid}_admin_user_policy"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action   = "*",
        Effect   = "Allow",
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "admin_user_policy_attach" {
  user       = aws_iam_user.admin_user.name
  policy_arn = aws_iam_policy.admin_user_policy.arn
}

#############################
# Low-Privileged User (Initial Credentials)
#############################

resource "aws_iam_user" "low_priv_user" {
  name = "${var.cgid}_low_priv_user"
}

resource "aws_iam_access_key" "low_priv_key" {
  user = aws_iam_user.low_priv_user.name
}

resource "aws_iam_policy" "low_priv_policy" {
  name = "${var.cgid}_low_priv_policy"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect: "Allow",
        Action: [
          "elasticbeanstalk:DescribeApplications",
          "elasticbeanstalk:DescribeApplicationVersions",
          "elasticbeanstalk:DescribeConfigurationSettings",
          "elasticbeanstalk:DescribeEnvironmentHealth",
          "elasticbeanstalk:DescribeEnvironmentResources",
          "elasticbeanstalk:DescribeEnvironments",
          "elasticbeanstalk:DescribeEvents",
          "elasticbeanstalk:ListAvailableSolutionStacks",
          "elasticbeanstalk:ListTagsForResource",
          "ec2:DescribeSubnets"
        ],
        Resource: "*"
      },
      {
        Effect: "Allow",
        Action: [
          "s3:*"
        ],
        Resource: [
          "arn:aws:s3:::elasticbeanstalk*", 
          "arn:aws:s3:::elasticbeanstalk*/*"
        ] 
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "low_priv_policy_attach" {
  user       = aws_iam_user.low_priv_user.name
  policy_arn = aws_iam_policy.low_priv_policy.arn
}

#############################
# Secondary Credentials (Discovered in EB Config)
#############################

resource "aws_iam_user" "secondary_user" {
  name = "${var.cgid}_secondary_user"
}

resource "aws_iam_access_key" "secondary_key" {
  user = aws_iam_user.secondary_user.name
}

resource "aws_iam_policy" "secondary_policy" {
  name = "${var.cgid}_secondary_policy"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "iam:CreateAccessKey"
        ],
        Resource = "*"
      },
      {
        Effect = "Allow",
        Action = [
          "iam:ListRoles",
          "iam:GetRole",
          "iam:ListPolicies",
          "iam:GetPolicy",
          "iam:ListPolicyVersions",
          "iam:GetPolicyVersion",
          "iam:ListUsers",
          "iam:GetUser",
          "iam:ListGroups",
          "iam:GetGroup",
          "iam:ListAttachedUserPolicies",
          "iam:ListAttachedRolePolicies",
          "iam:GetRolePolicy"
        ],
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "secondary_policy_attach" {
  user       = aws_iam_user.secondary_user.name
  policy_arn = aws_iam_policy.secondary_policy.arn
}

# Role for EB EC2 Instances
resource "aws_iam_role" "eb_instance_role" {
  name = "${var.cgid}_eb_instance_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "${var.cgid}_eb_instance_profile"
  role = aws_iam_role.eb_instance_role.name
}

# Role for the Elastic Beanstalk service
resource "aws_iam_role" "eb_service_role" {
  name = "${var.cgid}_eb_service_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_secretsmanager_secret" "final_flag" {
  name = "${var.cgid}_final_flag"
}

resource "aws_secretsmanager_secret_version" "final_flag" {
  secret_id     = aws_secretsmanager_secret.final_flag.id
  secret_string = var.final_flag
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "cg-vpc-${var.cgid}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "cg-igw-${var.cgid}"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "cg-subnet-${var.cgid}"
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "cg-route-table-${var.cgid}"
  }
}

resource "aws_route" "route" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "route_table_association" {
  subnet_id      = aws_subnet.subnet.id
  route_table_id = aws_route_table.route_table.id
}

resource "aws_iam_role" "bedrock_agent_role" {
  name               = "bedrock_agent_basic_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17",
    Statement = [
      {
        Action    = "sts:AssumeRole",
        Effect    = "Allow",
        Principal = {
          Service = "bedrock.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "bedrock_agent_policy" {
  name   = "bedrock_agent_basic_role_policy_${var.cgid}"
  role   = aws_iam_role.bedrock_agent_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "bedrock:InvokeModel",
          "bedrock:InvokeModelWithResponseStream"
        ]
        Resource = "arn:aws:bedrock:${var.region}::foundation-model/${var.agent_model_id}"
      }
    ]
  })
}

resource "aws_bedrockagent_agent_action_group" "inventory_tool" {
  agent_id      = aws_bedrockagent_agent.operations_agent.id
  agent_version = "DRAFT"
  action_group_name = "InventoryTool"
  description = "Action group exposing lambda function that inventories cloud resources"
  skip_resource_in_use_check = true
  action_group_executor {
    lambda = aws_lambda_function.inventory_lambda.arn
  }
  function_schema {
    member_functions {
      functions {
        name        = "LIST_IAM_ROLES"
        description = "Lists up to 100 IAM roles in the current account"
      }
      functions {
        name        = "LIST_IAM_USERS"
        description = "Lists up to 100 IAM users in the current account"
      }
      functions {
        name        = "LIST_EC2_INSTANCES"
        description = "Lists up to 100 EC2 instances in the current account"
      }
      functions {
        name        = "LIST_S3_BUCKETS"
        description = "Lists up to 100 S3 buckets in the current account"
      }
      functions {
        name        = "LIST_ALL"
        description = "Provides a listing of IAM roles, users, EC2 instances, and S3 Buckets in the current account"
      }
    }
  }
}

#############################
# Starting User (Initial Credentials)
#############################

resource "aws_iam_user" "starting_user" {
  name = "grace_${var.cgid}"
}

resource "aws_iam_access_key" "starting_user_key" {
  user = aws_iam_user.starting_user.name
}

# Iam enumeration is not part of the challenge. Might as well make it easy
resource "aws_iam_user_policy_attachment" "starting_user_iam_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_policy" "starting_user_bedrock_policy" {
  name = "agent_access_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "BedrockReadOnly"
        Effect = "Allow"
        Action = [
          "bedrock:Get*",
          "bedrock:List*"
        ],
        Resource = "*"
      },
      {
        Sid    = "InvokeOperationsAgent"
        Effect = "Allow",
        Action = [
          "bedrock:InvokeAgent"
        ],
        Resource = "arn:aws:bedrock:${var.region}:${data.aws_caller_identity.aws-account-id.account_id}:agent-alias/${aws_bedrockagent_agent.operations_agent.agent_id}/*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "starting_user_bedrock_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = aws_iam_policy.starting_user_bedrock_policy.arn
}

resource "aws_iam_policy" "starting_user_deployment_policy" {
  name = "lambda_deployment_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "LambdaUpdateAccess"
        Effect = "Allow",
        Action = [
          "lambda:CreateAlias",
          "lambda:GetAlias",
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:ListAliases",
          "lambda:ListVersionsByFunction",
          "lambda:PublishVersion",
          "lambda:UpdateAlias",
          "lambda:UpdateFunctionCode",
          "lambda:UpdateFunctionConfiguration"
        ],
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "starting_user_deployment_policy_attachment" {
