resource "aws_cognito_user_pool" "ctf_pool" {
  name = "CognitoCTF-${var.cgid}"
  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  lambda_config {
    post_confirmation = aws_lambda_function.test_lambda.arn
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  auto_verified_attributes = ["email"]

  user_attribute_update_settings {
    attributes_require_verification_before_update = ["email"]
  }

  email_configuration {
    email_sending_account = "COGNITO_DEFAULT"
  }

  schema {
    name                = "access"
    mutable             = true
    attribute_data_type = "String"
  }

  schema {
    name                = "email"
    required            = true
    attribute_data_type = "String"
  }

  schema {
    name                = "given_name"
    required            = true
    attribute_data_type = "String"
  }

  schema {
    name                = "family_name"
    required            = true
    attribute_data_type = "String"
  }

  password_policy {
    minimum_length                   = 8
    require_uppercase                = true
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  username_attributes = ["email"]

  username_configuration {
    case_sensitive = false
  }

  mfa_configuration = "OFF"
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "cognito_identitypool-${var.cgid}"
  allow_unauthenticated_identities = false
  allow_classic_flow               = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.cognito_client.id
